-- Additive V5 tables; preserve existing player data.
CREATE TABLE IF NOT EXISTS eq5_wallet(user_id BIGINT UNSIGNED PRIMARY KEY,earned BIGINT UNSIGNED NOT NULL DEFAULT 0,spent BIGINT UNSIGNED NOT NULL DEFAULT 0,state LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eq5_pets(user_id BIGINT UNSIGNED PRIMARY KEY,state LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eq5_farms(user_id BIGINT UNSIGNED PRIMARY KEY,state LONGTEXT NOT NULL,updated_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eq5_checkins(user_id BIGINT UNSIGNED NOT NULL,day DATE NOT NULL,streak SMALLINT UNSIGNED NOT NULL,reward_coins BIGINT UNSIGNED NOT NULL,claimed_at BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eq5_events(user_id BIGINT UNSIGNED NOT NULL,event_key VARCHAR(64) NOT NULL,payload_hash VARCHAR(64) NOT NULL,result LONGTEXT NOT NULL,created_at BIGINT UNSIGNED NOT NULL,PRIMARY KEY(user_id,event_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eq5_live(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,owner_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,room_key VARCHAR(80) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL,created_at BIGINT UNSIGNED NOT NULL,seen_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS eq5_live_chat(id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,room_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,body VARCHAR(600) NOT NULL,created_at BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
